  $('save-playback').onclick=async()=>{if(!playbackPreferences)return;const button=$('save-playback');button.disabled=true;try{playbackPreferences=await api('/api/voice-studio/music-preferences',{mode:$('playback').value,revision:playbackPreferences.revision});$('playback-status').textContent='已保存默认：'+playbackPreferences.label+' · 下次普通点歌沿用';toast('默认方式已保存，已排队任务保持原方式。');}catch(cause){error(cause);}finally{if(element.isConnected)button.disabled=false;}};
  $('playback').onchange=()=>{$('playback-status').textContent='本次选择已更改；点击保存才会改变下次默认。';};
  async function checkComponents(){try{const value=await api('/api/voice-components');if(!element.isConnected)return;generationBlocked=value.components.some(c=>c.status!=='present')&&!value.localFiles.singingEnvironment;const host=$('components-top');host.hidden=!generationBlocked;if(generationBlocked&&!componentPanelMounted){componentPanelMounted=true;host.innerHTML='<p class="notice">本地语音与翻唱运行组件尚未导入。请先导入下方组件，再检查模型；导入完成并就绪后可使用制作功能。搜歌与曲库管理仍可使用。</p>';mountVoiceComponentsPanel(host,{api,esc});}for(const button of element.querySelectorAll('[data-song-send]')){button.disabled=generationBlocked;button.title=generationBlocked?'请先导入语音组件并配置模型':'';}}catch{}}
  queueMicrotask(loadPlayback);queueMicrotask(checkComponents);
  const messages={NETEASE_CONNECTION_FAILED:'连接网易云失败，请稍后重试。',NETEASE_QR_UNAVAILABLE:'暂时无法生成二维码，请稍后重试。',NETEASE_LOGIN_FAILED:'网易云登录检查暂未完成，正在继续重试。',NETEASE_LOGIN_COOKIE_MISSING:'手机已授权，但尚未取得登录凭据，后台正在继续检查。',NETEASE_LOGIN_VERIFY_FAILED:'暂时无法确认登录状态，已保留本机凭据。',NETEASE_SECURE_STORAGE_UNAVAILABLE:'Windows 凭据保护不可用，未保存登录信息。',SONG_SEARCH_UNAVAILABLE:'网易云暂未返回搜索结果，请稍后重试或直接提供歌曲链接。',NETEASE_SEARCH_INVALID:'请输入100字以内的歌名或歌手。'};
  const error=e=>{if(element.isConnected)$('error').textContent=messages[e.message]??(/^NETEASE_/.test(e.message)?'网易云请求未完成，请稍后重试。':e.message);};
  const account=value=>{if(!element.isConnected)return;if(value.loggedIn&&!$('qr').hidden)stopQr();if(value.loggedIn&&!wasLoggedIn)$('error').textContent='';wasLoggedIn=value.loggedIn;$('account').textContent=value.loggedIn?'已保存登录 · '+(value.nickname||'网易云用户')+(value.valid||value.verifiedAt?' · 已核验':''):(['confirm','saving','retrying','official-window'].includes(value.login?.state)?({'official-window':'请在打开的网易云官方窗口点击登录，并扫码确认。',confirm:'已扫码，请在手机上确认登录。',saving:'手机已授权，正在保存登录状态…',retrying:messages[value.login?.error]??'登录检查遇到网络波动，后台仍在继续检查。'})[value.login.state]:'尚未登录 · 仍可搜索公开歌曲');$('logout').hidden=!value.loggedIn;$('login').textContent=value.loggedIn?'更换扫码账号':'备用扫码登录';};
  const selectedSongs=new Set(),songKey=s=>s.kind+':'+s.id;
  const visibleSongs=()=>songs.filter(song=>[song.title,song.artist].join(' ').toLocaleLowerCase().includes($('filter').value.trim().toLocaleLowerCase()));
  const popover=document.createElement('div');popover.className='music-song-popover';popover.setAttribute('popover','auto');popover.setAttribute('role','dialog');popover.setAttribute('aria-label','歌曲详情');document.body.append(popover);let hideTimer,activeSong;
  const closeSong=()=>{try{if(popover.matches(':popover-open'))popover.hidePopover();}catch{}popover.hidden=true;activeSong=null;};
  function showSong(button){const song=songs.find(s=>songKey(s)===button.dataset.mDetails);if(!song)return;clearTimeout(hideTimer);activeSong=song;const detail=[song.artist,song.kind==='vocal-source'?'导入人声':song.playbackMode==='full'?'完整翻唱 · '+(song.segmentCount??1)+'段':'1分钟片段',({cute:'明亮可爱（B）',natural:'自然可爱（A）',gentle:'温柔'})[song.style],Number.isFinite(song.durationSeconds)?Math.round(song.durationSeconds)+'秒':'',song.busy?'正在使用':'',song.savedAt?'保存于 '+new Date(song.savedAt).toLocaleString():''].filter(Boolean).join(' · ');popover.innerHTML='<strong>'+esc(song.title)+'</strong><p>'+esc(detail)+'</p><div class="actions"><button class="button small" data-m-reveal '+(!window.desktop?.revealSong?'disabled':'')+'>打开文件位置</button><button class="button small danger" data-m-delete-one '+(song.busy?'disabled':'')+'>删除歌曲</button><button class="button small" data-m-close-detail>关闭详情</button></div>';popover.hidden=false;if(popover.showPopover&&!popover.matches(':popover-open'))popover.showPopover();const rect=button.getBoundingClientRect(),box=popover.getBoundingClientRect();popover.style.left=Math.max(12,Math.min(rect.left,innerWidth-box.width-12))+'px';popover.style.top=(rect.bottom+box.height+12<innerHeight?rect.bottom+8:Math.max(12,rect.top-box.height-8))+'px';}
  function selectionStatus(){const visible=visibleSongs().filter(s=>!s.busy);$('selection').textContent=selectedSongs.size?'已勾选 '+selectedSongs.size+' 首':'未选择';$('delete-selected').disabled=!selectedSongs.size;$('select-all').checked=!!visible.length&&visible.every(s=>selectedSongs.has(songKey(s)));$('select-all').indeterminate=visible.some(s=>selectedSongs.has(songKey(s)))&&!$('select-all').checked;}
  function renderSongs(){const items=visibleSongs(),valid=new Set(songs.filter(s=>!s.busy).map(songKey));for(const key of selectedSongs)if(!valid.has(key))selectedSongs.delete(key);$('count').textContent='（'+songs.length+'首）';const html=items.length?'<ul class="music-song-bubbles">'+items.map(song=>'<li class="music-song-chip"><input type="checkbox" data-m-select="'+esc(songKey(song))+'" aria-label="选择 '+esc(song.title)+'" '+(selectedSongs.has(songKey(song))?'checked':'')+' '+(song.busy?'disabled':'')+'><button class="music-song-title" type="button" data-m-details="'+esc(songKey(song))+'">'+esc(song.title)+'</button></li>').join('')+'</ul>':'<p class="subtle">'+(songs.length?'没有匹配的音乐。':'导入人声或点歌制作完成后，会自动加入曲库。')+'</p>';if(html!==last){$('songs').innerHTML=html;last=html;}selectionStatus();}
  async function deleteSongs(items){if(!items.length||!window.confirm('确认删除所选 '+items.length+' 首音乐？完整歌曲的所有分段将一起删除，此操作不可撤销。'))return;try{closeSong();const value=await api('/api/voice-studio/delete-songs',{items:items.map(({id,kind})=>({id,kind})),confirmed:true});selectedSongs.clear();last='';toast('已删除 '+value.deleted+' 首音乐'+(value.cleanupPending?'，部分缓存等待清理。':'。'));await refresh();}catch(cause){error(cause);}}
  $('songs').addEventListener('change',event=>{const input=event.target.closest('[data-m-select]');if(!input)return;if(input.checked)selectedSongs.add(input.dataset.mSelect);else selectedSongs.delete(input.dataset.mSelect);selectionStatus();});
  $('songs').addEventListener('mouseover',event=>{const button=event.target.closest('[data-m-details]');if(button)showSong(button);});$('songs').addEventListener('focusin',event=>{const button=event.target.closest('[data-m-details]');if(button)showSong(button);});$('songs').addEventListener('click',event=>{const button=event.target.closest('[data-m-details]');if(button)showSong(button);});$('songs').addEventListener('mouseleave',()=>{hideTimer=setTimeout(closeSong,220);});popover.onkeydown=event=>{if(event.key==='Escape')closeSong();};popover.onmouseenter=()=>clearTimeout(hideTimer);popover.onmouseleave=()=>{hideTimer=setTimeout(closeSong,220);};popover.onclick=async event=>{if(event.target.closest('[data-m-close-detail]'))closeSong();if(event.target.closest('[data-m-delete-one]')&&activeSong)await deleteSongs([activeSong]);if(event.target.closest('[data-m-reveal]')&&activeSong)try{await window.desktop.revealSong({id:activeSong.id,kind:activeSong.kind});}catch(cause){error(cause);}};
  $('select-all').onchange=event=>{for(const song of visibleSongs().filter(s=>!s.busy)){if(event.target.checked)selectedSongs.add(songKey(song));else selectedSongs.delete(songKey(song));}last='';renderSongs();};$('clear-selection').onclick=()=>{selectedSongs.clear();last='';renderSongs();};$('delete-selected').onclick=()=>deleteSongs(songs.filter(s=>selectedSongs.has(songKey(s))));
  $('save-retention').onclick=async event=>{if(!playbackPreferences)return;const maxSongs=Number($('max-songs').value);if(!Number.isInteger(maxSongs)||maxSongs<0||maxSongs>500)return error(Error('保留数量请选择0–500的整数。'));if(maxSongs&&songs.filter(s=>s.kind==='rendered-song').length>maxSongs&&!window.confirm('保存后将清理超过上限、最旧且未在使用的成品，导入的人声素材保留。确认保存？'))return;const button=event.currentTarget;button.disabled=true;try{playbackPreferences=await api('/api/voice-studio/music-preferences',{maxSongs,revision:playbackPreferences.revision});$('retention-status').textContent='已保存：'+(maxSongs?maxSongs+'首':'不限制');await refresh();}catch(cause){error(cause);}finally{if(button.isConnected)button.disabled=false;}};
  const popoverCleanup=new MutationObserver(()=>{if(!element.isConnected){clearTimeout(hideTimer);closeSong();popover.remove();popoverCleanup.disconnect();}});popoverCleanup.observe(document.body,{childList:true,subtree:true});
  async function refresh(){if(refreshing)return;refreshing=true;clearTimeout(timer);try{const value=await api('/api/music');if(!element.isConnected)return;account(value.account);$('send-mode').hidden=value.sendingMode!=='foreground';$('send-mode').textContent='当前为前台模式：音乐搜索、登录和曲库仍可使用；原生语音和唱歌发微信已停用。需要发送歌曲语音时，请在设置中切换到 Hook 模式。';songs=value.songs;renderSongs();void checkComponents();}catch(e){error(e);}finally{refreshing=false;if(element.isConnected)timer=setTimeout(refresh,5000);}}
  async function action(name,body={}){return api('/api/music/'+name,body);}
  function stopQr(){qrEpoch++;clearTimeout(qrTimer);$('qr').hidden=true;$('image').removeAttribute('src');}
  $('official').onclick=async()=>{const button=$('official');button.disabled=true;$('error').textContent='';stopQr();try{await action('official-login');toast('已打开网易云官网，请在官方窗口完成登录。');}catch(e){error(e);}finally{if(element.isConnected)button.disabled=false;}};
  $('cancel').onclick=()=>{stopQr();void action('cancel').catch(error);};
  $('login').onclick=async()=>{if(busy)return;busy=true;stopQr();const attempt=qrEpoch;$('login').disabled=true;$('error').textContent='';try{const value=await action('login');if(!element.isConnected||attempt!==qrEpoch)return;$('image').src=value.qrImage;$('qr').hidden=false;$('qr-status').textContent='使用网易云音乐手机应用扫码，并在手机上确认登录。';const poll=async()=>{if(!element.isConnected||attempt!==qrEpoch)return;try{const state=await action('check');if(!element.isConnected||attempt!==qrEpoch)return;if(state.state==='logged-in'){stopQr();account(state);toast('网易云登录已保存。');return;}if(state.state==='expired'||Date.now()>value.expiresAt){$('qr-status').textContent='二维码已过期，请重新生成。';$('image').removeAttribute('src');return;}$('qr-status').textContent=state.state==='confirm'?'已扫码，请在手机上确认登录。':'等待手机扫码…';qrTimer=setTimeout(poll,3000);}catch(e){if(!element.isConnected||attempt!==qrEpoch)return;error(e);$('qr-status').textContent=Date.now()>value.expiresAt?'二维码已过期，请重新生成。':'登录检查暂时失败，正在继续重试；也可以点击检查登录状态。';if(Date.now()<value.expiresAt)qrTimer=setTimeout(poll,4000);}};qrTimer=setTimeout(poll,3000);}catch(e){error(e);}finally{busy=false;if(element.isConnected)$('login').disabled=false;}};
  $('verify').onclick=async()=>{const button=$('verify');button.disabled=true;try{const value=await action('verify');account(value);if(value.expired)toast('登录已失效，请重新扫码。');}catch(e){error(e);}finally{if(element.isConnected)button.disabled=false;}};
